package com.bank.payments.application;

import com.bank.payments.adapters.in.rest.PayOrderRequest;
import com.bank.payments.adapters.in.rest.PayOrderResponse;
import com.bank.payments.domain.error.BusinessError;
import com.bank.payments.domain.model.Account;
import com.bank.payments.domain.model.Order;
import com.bank.payments.domain.port.AccountRepository;
import com.bank.payments.domain.port.MovementGateway;
import com.bank.payments.domain.port.OrderRepository;
import java.math.BigDecimal;
import java.math.RoundingMode;

/** Use case PayOrder (legacy PAGOORD, with the logic of PAGODEB absorbed). */
public class PayOrderService {

    private static final BigDecimal LARGE_ORDER_THRESHOLD = new BigDecimal("50000");
    private static final BigDecimal COMMISSION_WEB = new BigDecimal("1.00");
    private static final BigDecimal COMMISSION_OTHER = new BigDecimal("2.50");
    private static final BigDecimal COMMISSION_ZERO = new BigDecimal("0.00");

    private final OrderRepository orderRepository;
    private final AccountRepository accountRepository;
    private final MovementGateway movementGateway;

    public PayOrderService(OrderRepository orderRepository,
                           AccountRepository accountRepository,
                           MovementGateway movementGateway) {
        this.orderRepository = orderRepository;
        this.accountRepository = accountRepository;
        this.movementGateway = movementGateway;
    }

    public PayOrderResponse execute(PayOrderRequest request) {
        // 2100-VALIDAR-ENTRADA (legacy order: order number, account type, channel, approval key)
        String orderNumberText = fixed(request.orderNumber(), 7);
        String accountTypeText = fixed(request.accountType(), 3);
        String channelText = fixed(request.channel(), 3);
        String keyText = fixed(request.approvalKey(), 6);

        if (!isNumeric(orderNumberText) || isAllZeros(orderNumberText)) {
            throw new BusinessError("INVALID_ORDER_NUMBER", "NUMERO DE ORDEN INVALIDO",
                    "NUMERO DE ORDEN INVALIDO");
        }
        if (!accountTypeText.equals("CTE") && !accountTypeText.equals("AHO")
                && !accountTypeText.equals("VIR")) {
            throw new BusinessError("ACCOUNT_TYPE_NOT_ALLOWED", "TIPO DE CUENTA NO PERMITIDO",
                    "TIPO DE CUENTA NO PERMITIDO");
        }
        if (!channelText.equals("WEB") && !channelText.equals("OFI")) {
            throw new BusinessError("CHANNEL_NOT_ALLOWED", "CANAL NO PERMITIDO",
                    "CANAL NO PERMITIDO");
        }
        if (channelText.equals("OFI") && keyText.trim().isEmpty() && isAllSpaces(keyText)) {
            throw new BusinessError("APPROVAL_KEY_REQUIRED", "CLAVE DE APROBACION REQUERIDA",
                    "CLAVE DE APROBACION REQUERIDA");
        }

        // 2200-LEER-ORDEN
        Integer orderNumber = Integer.valueOf(Integer.parseInt(orderNumberText));
        Integer company = Integer.valueOf(Integer.parseInt(fixed(request.company(), 5).trim()));
        Order order = orderRepository.findByKey(orderNumber, company).orElseThrow(
                () -> new BusinessError("ORDER_NOT_FOUND", "ORDEN NO EXISTE", "ORDEN NO EXISTE"));
        if (!"P".equals(order.status())) {
            throw new BusinessError("ORDER_NOT_PENDING", "ORDEN NO ESTA PENDIENTE",
                    "ORDEN NO ESTA PENDIENTE");
        }
        if (request.amount().compareTo(order.orderValue()) != 0) {
            throw new BusinessError("AMOUNT_MISMATCH", "VALOR NO COINCIDE CON LA ORDEN",
                    "VALOR NO COINCIDE CON LA ORDEN");
        }

        // 2300-CALCULAR-COMISION
        BigDecimal commission;
        if (order.orderValue().compareTo(LARGE_ORDER_THRESHOLD) >= 0) {
            commission = COMMISSION_ZERO;
        } else if (channelText.equals("WEB")) {
            commission = COMMISSION_WEB;
        } else {
            commission = COMMISSION_OTHER;
        }
        BigDecimal total = order.orderValue().add(commission).setScale(2, RoundingMode.DOWN);

        // 2400-DEBITAR-CUENTA (logic of PAGODEB)
        Long accountNumber = Long.valueOf(Long.parseLong(fixed(request.account(), 10).trim()));
        Account account = accountRepository.findByNumber(accountNumber).orElseThrow(
                () -> new BusinessError("PAYMENT_INVALID_ACCOUNT", "CUENTA NO VALIDA",
                        "CUENTA NO VALIDA"));
        if (!fixed(account.accountType(), 3).equals(accountTypeText)) {
            throw new BusinessError("PAYMENT_INVALID_ACCOUNT", "CUENTA NO VALIDA",
                    "CUENTA NO VALIDA");
        }
        if (!"A".equals(account.status())) {
            throw new BusinessError("PAYMENT_ACCOUNT_INACTIVE", "CUENTA INACTIVA",
                    "CUENTA INACTIVA");
        }
        if (account.balance().compareTo(total) < 0) {
            throw new BusinessError("PAYMENT_INSUFFICIENT_FUNDS", "SALDO INSUFICIENTE",
                    "SALDO INSUFICIENTE");
        }
        BigDecimal newBalance = account.balance().subtract(total).setScale(2, RoundingMode.DOWN);
        accountRepository.updateBalance(accountNumber, newBalance);

        // 2500-REGISTRAR-PAGO
        long movementNumber = movementGateway.registerMovement(order.orderNumber());
        orderRepository.markPaid(orderNumber, company, Long.valueOf(movementNumber), commission);

        // 2600-ENVIAR-RESULTADO
        return new PayOrderResponse(
                String.format("%07d", order.orderNumber()),
                commission,
                Long.valueOf(movementNumber),
                "PAGO REALIZADO");
    }

    /** Alphanumeric field semantics: padded with spaces / truncated to the declared length. */
    private static String fixed(String value, int length) {
        String v = value == null ? "" : value;
        if (v.length() > length) {
            return v.substring(0, length);
        }
        StringBuilder sb = new StringBuilder(v);
        while (sb.length() < length) {
            sb.append(' ');
        }
        return sb.toString();
    }

    private static boolean isNumeric(String s) {
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (c < '0' || c > '9') {
                return false;
            }
        }
        return true;
    }

    private static boolean isAllZeros(String s) {
        for (int i = 0; i < s.length(); i++) {
            if (s.charAt(i) != '0') {
                return false;
            }
        }
        return true;
    }

    private static boolean isAllSpaces(String s) {
        for (int i = 0; i < s.length(); i++) {
            if (s.charAt(i) != ' ') {
                return false;
            }
        }
        return true;
    }
}

