### src/test/java/com/bank/payments/application/PayOrderServiceTest.java
```
package com.bank.payments.application;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

import com.bank.payments.adapters.in.rest.PayOrderRequest;
import com.bank.payments.adapters.in.rest.PayOrderResponse;
import com.bank.payments.domain.error.BusinessError;
import com.bank.payments.domain.model.Account;
import com.bank.payments.domain.model.Order;
import com.bank.payments.domain.port.AccountRepository;
import com.bank.payments.domain.port.MovementGateway;
import com.bank.payments.domain.port.OrderRepository;
import java.math.BigDecimal;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Optional;
import org.junit.jupiter.api.Test;

class PayOrderServiceTest {

    private static final String BLANK_KEY = "      ";

    /** In-memory world: fakes of the three ports and a record of every call, in order. */
    private static final class World {
        final Map<String, Order> orders = new HashMap<>();
        final Map<Long, Account> accounts = new HashMap<>();
        final List<String> calls = new ArrayList<>();
        final List<String> writes = new ArrayList<>();
        long movementToReturn = 9000000001L;

        void order(Integer number, Integer company, String status, String value) {
            orders.put(number + "/" + company,
                    new Order(number, company, status, new BigDecimal(value), null, null));
        }

        void account(Long number, String type, String balance, String status) {
            accounts.put(number, new Account(number, type, new BigDecimal(balance), status));
        }

        PayOrderService service() {
            OrderRepository orderRepository = new OrderRepository() {
                @Override
                public Optional<Order> findByKey(Integer orderNumber, Integer company) {
                    calls.add("order.findByKey(" + orderNumber + "," + company + ")");
                    return Optional.ofNullable(orders.get(orderNumber + "/" + company));
                }

                @Override
                public void markPaid(Integer orderNumber, Integer company, Long movementNumber,
                                     BigDecimal commission) {
                    String c = "order.markPaid(" + orderNumber + "," + company + "," + movementNumber + ","
                            + commission.toPlainString() + ")";
                    calls.add(c);
                    writes.add(c);
                }
            };
            AccountRepository accountRepository = new AccountRepository() {
                @Override
                public Optional<Account> findByNumber(Long accountNumber) {
                    calls.add("account.findByNumber(" + accountNumber + ")");
                    return Optional.ofNullable(accounts.get(accountNumber));
                }

                @Override
                public void updateBalance(Long accountNumber, BigDecimal balance) {
                    String c = "account.updateBalance(" + accountNumber + "," + balance.toPlainString() + ")";
                    calls.add(c);
                    writes.add(c);
                }
            };
            MovementGateway movementGateway = orderNumber -> {
                String c = "movement.register(" + orderNumber + ")";
                calls.add(c);
                writes.add(c);
                return movementToReturn;
            };
            return new PayOrderService(orderRepository, accountRepository, movementGateway);
        }
    }

    private static World standardWorld() {
        World w = new World();
        w.order(1234567, 10, "P", "1000.00");
        w.account(1234567890L, "AHO", "5000.00", "A");
        return w;
    }

    private static PayOrderRequest request(String orderNumber, String accountType, String channel,
                                           String key, String amount) {
        return new PayOrderRequest(orderNumber, "00010", accountType, "1234567890",
                new BigDecimal(amount), channel, key);
    }

    private static PayOrderRequest webRequest() {
        return request("1234567", "AHO", "WEB", BLANK_KEY, "1000.00");
    }

    private static void assertRejected(World w, PayOrderRequest request, String code, String legacyCode) {
        assertThatThrownBy(() -> w.service().execute(request))
                .isInstanceOf(BusinessError.class)
                .satisfies(e -> {
                    BusinessError be = (BusinessError) e;
                    assertThat(be.code()).isEqualTo(code);
                    assertThat(be.legacyCode()).isEqualTo(legacyCode);
                });
    }

    // ---------- RULE-007: order number ----------

    @Test
    void rule_007_order_number_is_zero() {
        World w = standardWorld();
        assertRejected(w, request("0000000", "AHO", "WEB", BLANK_KEY, "1000.00"),
                "INVALID_ORDER_NUMBER", "NUMERO DE ORDEN INVALIDO");
        assertThat(w.calls).isEmpty();
    }

    @Test
    void rule_007_order_number_contains_letters() {
        World w = standardWorld();
        assertRejected(w, request("12A4567", "AHO", "WEB", BLANK_KEY, "1000.00"),
                "INVALID_ORDER_NUMBER", "NUMERO DE ORDEN INVALIDO");
        assertThat(w.calls).isEmpty();
    }

    @Test
    void rule_007_order_number_blank_is_not_numeric() {
        World w = standardWorld();
        assertRejected(w, request("       ", "AHO", "WEB", BLANK_KEY, "1000.00"),
                "INVALID_ORDER_NUMBER", "NUMERO DE ORDEN INVALIDO");
        assertThat(w.calls).isEmpty();
    }

    @Test
    void rule_007_order_number_error_wins_over_account_type_channel_and_key() {
        World w = standardWorld();
        assertRejected(w, request("0000000", "XYZ", "ATM", BLANK_KEY, "1000.00"),
                "INVALID_ORDER_NUMBER", "NUMERO DE ORDEN INVALIDO");
        assertThat(w.calls).isEmpty();
    }

    // ---------- RULE-008: account types ----------

    @Test
    void rule_008_account_type_unknown_is_rejected() {
        World w = standardWorld();
        assertRejected(w, request("1234567", "XYZ", "WEB", BLANK_KEY, "1000.00"),
                "ACCOUNT_TYPE_NOT_ALLOWED", "TIPO DE CUENTA NO PERMITIDO");
        assertThat(w.calls).isEmpty();
    }

    @Test
    void rule_008_account_type_is_case_sensitive() {
        World w = standardWorld();
        assertRejected(w, request("1234567", "aho", "WEB", BLANK_KEY, "1000.00"),
                "ACCOUNT_TYPE_NOT_ALLOWED", "TIPO DE CUENTA NO PERMITIDO");
        assertThat(w.calls).isEmpty();
    }

    @Test
    void rule_008_account_type_error_wins_over_channel_error() {
        World w = standardWorld();
        assertRejected(w, request("1234567", "XYZ", "ATM", BLANK_KEY, "1000.00"),
                "ACCOUNT_TYPE_NOT_ALLOWED", "TIPO DE CUENTA NO PERMITIDO");
        assertThat(w.calls).isEmpty();
    }

    @Test
    void rule_008_account_type_AHO_accepted() {
        World w = standardWorld();
        PayOrderResponse r = w.service().execute(request("1234567", "AHO", "WEB", BLANK_KEY, "1000.00"));
        assertThat(r.resultMessage()).isEqualTo("PAGO REALIZADO");
    }

    @Test
    void rule_008_account_type_CTE_accepted() {
        World w = standardWorld();
        w.account(1234567890L, "CTE", "5000.00", "A");
        PayOrderResponse r = w.service().execute(request("1234567", "CTE", "WEB", BLANK_KEY, "1000.00"));
        assertThat(r.resultMessage()).isEqualTo("PAGO REALIZADO");
    }

    @Test
    void rule_008_account_type_VIR_accepted() {
        World w = standardWorld();
        w.account(1234567890L, "VIR", "5000.00", "A");
        PayOrderResponse r = w.service().execute(request("1234567", "VIR", "WEB", BLANK_KEY, "1000.00"));
        assertThat(r.resultMessage()).isEqualTo("PAGO REALIZADO");
    }

    // ---------- RULE-009: channels ----------

    @Test
    void rule_009_channel_ATM_is_rejected() {
        World w = standardWorld();
