    private static final class World {
        final Map<String, Order> orders = new HashMap<>();
        final Map<Long, Account> accounts = new HashMap<>();
        final List<String> calls = new ArrayList<>();
        final List<String> writes = new ArrayList<>();
        long movementToReturn = 9000000001L;

        void order(Integer number, Integer company, String status, String value) {
            orders.put(number + "/" + company,
                    new Order(number, company, status, new BigDecimal(value), null, null));
        }

        void account(Long number, String type, String balance, String status) {
            accounts.put(number, new Account(number, type, new BigDecimal(balance), status));
        }

        PayOrderService service() {
            OrderRepository orderRepository = new OrderRepository() {
                @Override
                public Optional<Order> findByKey(Integer orderNumber, Integer company) {
                    calls.add("order.findByKey(" + orderNumber + "," + company + ")");
                    return Optional.ofNullable(orders.get(orderNumber + "/" + company));
                }

                @Override
                public void markPaid(Integer orderNumber, Integer company, Long movementNumber,
                                     BigDecimal commission) {
                    String c = "order.markPaid(" + orderNumber + "," + company + "," + movementNumber + ","
                            + commission.toPlainString() + ")";
                    calls.add(c);
                    writes.add(c);
                }
            };
            AccountRepository accountRepository = new AccountRepository() {
                @Override
                public Optional<Account> findByNumber(Long accountNumber) {
                    calls.add("account.findByNumber(" + accountNumber + ")");
                    return Optional.ofNullable(accounts.get(accountNumber));
                }

                @Override
                public void updateBalance(Long accountNumber, BigDecimal balance) {
                    String c = "account.updateBalance(" + accountNumber + "," + balance.toPlainString() + ")";
                    calls.add(c);
                    writes.add(c);
                }
