            MovementGateway movementGateway = orderNumber -> {
                String c = "movement.register(" + orderNumber + ")";
                calls.add(c);
                writes.add(c);
                return movementToReturn;
            };
            return new PayOrderService(orderRepository, accountRepository, movementGateway);
        }
    }

